public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]] = true;
    queue.add(start[0]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection from the queue
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0]) {
            return "can be travelled";
        }

        // Loop through all the paths from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            // If the path is not visited and leads to a new n-tersection, mark it as visited and add it to the queue
            if (!visited[paths[i][0]] && paths[i][1] == current) {
                visited[paths[i][0]] = true;
                queue.add(paths[i][0]);
            }
        }
    }

    // If the queue is empty and the ending n-tersection was not reached, return "cannot be travelled"
    return "cannot be travelled";
}
